const useChatDailyQuota = `-- name: UseChatDailyQuota :one
INSERT INTO chat_daily_usage (user_id,day,count) VALUES ($1,(now() AT TIME ZONE 'UTC')::date,1)
ON CONFLICT (user_id,day) DO UPDATE SET count=chat_daily_usage.count+1
WHERE $2::integer=0 OR chat_daily_usage.count<$2::integer RETURNING count
`

type UseChatDailyQuotaParams struct {
	UserID     uuid.UUID
	DailyLimit int32
}

func (q *Queries) UseChatDailyQuota(ctx context.Context, arg UseChatDailyQuotaParams) (int32, error) {
	row := q.db.QueryRow(ctx, useChatDailyQuota, arg.UserID, arg.DailyLimit)
	var count int32
	err := row.Scan(&count)
	return count, err
}
